package gal.rodrigosambade.blegattlab;
import android.Manifest; import android.bluetooth.*; import android.bluetooth.le.*; import android.content.pm.PackageManager; import android.os.*; import android.widget.*; import androidx.activity.result.*; import androidx.activity.result.contract.ActivityResultContracts; import androidx.annotation.NonNull; import androidx.appcompat.app.AppCompatActivity; import androidx.core.content.ContextCompat; import java.util.*;
public class MainActivity extends AppCompatActivity{
 BluetoothAdapter adapter;BluetoothLeScanner scanner;BluetoothGatt gatt;List<BluetoothDevice> found=new ArrayList<>();List<String> labels=new ArrayList<>();ArrayAdapter<String> listAdapter;TextView status,gattText;Handler h=new Handler(Looper.getMainLooper());boolean scanning;
 ActivityResultLauncher<String[]> perms=registerForActivityResult(new ActivityResultContracts.RequestMultiplePermissions(),r->scan());
 protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);status=findViewById(R.id.status);gattText=findViewById(R.id.gatt);ListView l=findViewById(R.id.devices);listAdapter=new ArrayAdapter<>(this,android.R.layout.simple_list_item_1,labels);l.setAdapter(listAdapter);l.setOnItemClickListener((p,v,pos,id)->connect(found.get(pos)));adapter=((BluetoothManager)getSystemService(BLUETOOTH_SERVICE)).getAdapter();findViewById(R.id.scan).setOnClickListener(v->ensure());if(adapter==null)status.setText("Sin Bluetooth");}
 boolean canScan(){return Build.VERSION.SDK_INT<31||ContextCompat.checkSelfPermission(this,Manifest.permission.BLUETOOTH_SCAN)==PackageManager.PERMISSION_GRANTED;}boolean canConnect(){return Build.VERSION.SDK_INT<31||ContextCompat.checkSelfPermission(this,Manifest.permission.BLUETOOTH_CONNECT)==PackageManager.PERMISSION_GRANTED;}
 void ensure(){if(adapter==null)return;List<String> m=new ArrayList<>();if(Build.VERSION.SDK_INT>=31){if(!canScan())m.add(Manifest.permission.BLUETOOTH_SCAN);if(!canConnect())m.add(Manifest.permission.BLUETOOTH_CONNECT);}else if(ContextCompat.checkSelfPermission(this,Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED)m.add(Manifest.permission.ACCESS_FINE_LOCATION);if(m.isEmpty())scan();else perms.launch(m.toArray(new String[0]));}
 void scan(){if(adapter==null||!canScan())return;scanner=adapter.getBluetoothLeScanner();if(scanner==null){status.setText("Activa Bluetooth");return;}found.clear();labels.clear();listAdapter.notifyDataSetChanged();scanning=true;scanner.startScan(cb);status.setText("Escaneando…");h.postDelayed(this::stop,10000);}
 void stop(){if(scanning&&scanner!=null&&canScan())scanner.stopScan(cb);scanning=false;status.setText("Encontrados: "+found.size());}
 ScanCallback cb=new ScanCallback(){public void onScanResult(int t,ScanResult r){BluetoothDevice d=r.getDevice();if(!found.contains(d)){found.add(d);String n=canConnect()?d.getName():null;labels.add((n==null?"(sin nombre)":n)+"\n"+d.getAddress()+" RSSI "+r.getRssi());listAdapter.notifyDataSetChanged();}}public void onScanFailed(int e){status.setText("Fallo scan "+e);}};
 void connect(BluetoothDevice d){stop();if(!canConnect()){ensure();return;}if(gatt!=null)gatt.close();gatt=d.connectGatt(this,false,gcb,BluetoothDevice.TRANSPORT_LE);status.setText("Conectando a "+d.getAddress());}
 BluetoothGattCallback gcb=new BluetoothGattCallback(){public void onConnectionStateChange(@NonNull BluetoothGatt g,int s,int n){if(n==BluetoothProfile.STATE_CONNECTED&&canConnect())g.discoverServices();else if(n==BluetoothProfile.STATE_DISCONNECTED)runOnUiThread(()->status.setText("Desconectado"));}public void onServicesDiscovered(@NonNull BluetoothGatt g,int s){StringBuilder b=new StringBuilder();for(BluetoothGattService sv:g.getServices()){b.append("SERVICE ").append(sv.getUuid()).append('\n');for(BluetoothGattCharacteristic c:sv.getCharacteristics())b.append("  CHAR ").append(c.getUuid()).append(" props=0x").append(Integer.toHexString(c.getProperties())).append('\n');}runOnUiThread(()->gattText.setText(b.toString()));}};
 protected void onDestroy(){stop();if(gatt!=null&&canConnect()){gatt.disconnect();gatt.close();}super.onDestroy();}
}
